<template>
  <section class="space-y-6">
    <header><p class="text-xs font-semibold uppercase tracking-[0.2em] text-indigo-600">Administration</p><h1 class="mt-1 text-2xl font-bold text-slate-950 sm:text-3xl">Guardian engagement review</h1><p class="mt-1 text-sm text-slate-500">Review requests, make decisions, publish guardian documents, and monitor acknowledgement state.</p></header>
    <p v-if="errorMessage" class="rounded-lg border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-800" role="alert">{{ errorMessage }}</p><p v-if="successMessage" class="rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800" role="status">{{ successMessage }}</p>

    <div class="flex max-w-full gap-2 overflow-x-auto border-b border-slate-200 pb-2"><button v-for="tab in tabs" :key="tab.key" type="button" :class="activeTab === tab.key ? 'bg-indigo-600 text-white' : 'bg-white text-slate-600 hover:bg-slate-50'" class="shrink-0 rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold" @click="activeTab = tab.key">{{ tab.label }}</button></div>

    <section v-if="activeTab === 'communications'" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div class="mb-4 flex items-center justify-between gap-3"><div><h2 class="font-bold text-slate-900">Communication requests</h2><p class="mt-1 text-xs text-slate-500">Respond to guardian requests and retain the request history.</p></div><button type="button" class="btn-secondary px-3 py-2 text-xs font-semibold" @click="loadAll">Refresh</button></div><div class="space-y-3"><article v-for="item in communications" :key="item.request_id" class="rounded-lg border border-slate-200 bg-slate-50 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold text-slate-900">{{ item.subject }}</p><p class="mt-1 text-xs text-slate-500">{{ item.guardian?.full_name }} · {{ item.student?.full_name || 'Account' }} · {{ item.category }}</p></div><span class="rounded-full bg-indigo-100 px-2 py-1 text-[10px] font-semibold text-indigo-700">{{ item.status }}</span></div><p class="mt-3 text-sm text-slate-700">{{ item.message }}</p><div class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-[1fr_auto]"><textarea v-model="communicationResponses[item.request_id]" rows="2" maxlength="4000" placeholder="Administrator response" class="rounded-lg border border-slate-300 px-3 py-2 text-sm"></textarea><div class="flex flex-wrap items-start gap-2"><button v-for="status in ['In Review', 'Responded', 'Rejected', 'Closed']" :key="status" type="button" class="btn-primary px-3 py-2 text-[11px] font-semibold" :disabled="busyKey === item.request_id" @click="respondCommunication(item, status)">{{ status }}</button></div></div></article><p v-if="!communications.length" class="text-sm text-slate-500">No communication requests require review.</p></div></section>

    <section v-else-if="activeTab === 'appointments'" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div class="mb-4"><h2 class="font-bold text-slate-900">Appointment requests</h2><p class="mt-1 text-xs text-slate-500">Only administrators can confirm the final meeting time.</p></div><div class="space-y-3"><article v-for="item in appointments" :key="item.appointment_id" class="rounded-lg border border-slate-200 bg-slate-50 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold text-slate-900">{{ item.guardian?.full_name }} · {{ item.student?.full_name || 'Account meeting' }}</p><p class="mt-1 text-sm text-slate-600">{{ item.purpose }}</p><p class="mt-1 text-xs text-slate-500">Preferred: {{ formatDateTime(item.preferred_start_at) }}–{{ formatTime(item.preferred_end_at) }}</p></div><span class="rounded-full bg-cyan-100 px-2 py-1 text-[10px] font-semibold text-cyan-700">{{ item.status }}</span></div><div class="mt-3 grid grid-cols-1 gap-2 md:grid-cols-3"><input v-model="appointmentDecisions[item.appointment_id].proposed_start_at" type="datetime-local" class="rounded-lg border border-slate-300 px-3 py-2 text-xs" /><input v-model="appointmentDecisions[item.appointment_id].proposed_end_at" type="datetime-local" class="rounded-lg border border-slate-300 px-3 py-2 text-xs" /><input v-model="appointmentDecisions[item.appointment_id].administrator_note" placeholder="Decision note" class="rounded-lg border border-slate-300 px-3 py-2 text-xs" /></div><div class="mt-2 flex flex-wrap gap-2"><button v-for="status in ['Proposed', 'Confirmed', 'Declined', 'Reschedule Requested', 'Completed', 'No Show']" :key="status" type="button" class="btn-primary px-3 py-2 text-[11px] font-semibold" :disabled="busyKey === item.appointment_id" @click="decideAppointment(item, status)">{{ status }}</button></div></article><p v-if="!appointments.length" class="text-sm text-slate-500">No appointment requests require review.</p></div></section>

    <section v-else-if="activeTab === 'discipline'" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div class="mb-4"><h2 class="font-bold text-slate-900">Disciplinary acknowledgements</h2><p class="mt-1 text-xs text-slate-500">Monitor whether guardians received significant guardian-visible notices.</p></div><div class="space-y-2"><article v-for="item in acknowledgements" :key="item.acknowledgement_id" class="flex flex-col gap-2 rounded-lg border border-slate-200 bg-slate-50 p-3 sm:flex-row sm:items-center sm:justify-between"><div><p class="font-semibold text-slate-900">{{ item.student?.full_name }} · {{ item.guardian?.full_name }}</p><p class="text-xs text-slate-500">{{ item.behavior_incident?.severity }} incident on {{ formatDate(item.behavior_incident?.incident_date) }}</p><p v-if="item.response_note" class="mt-1 text-sm text-slate-600">{{ item.response_note }}</p></div><span :class="item.status === 'Acknowledged' ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'" class="w-fit rounded-full px-2 py-1 text-[10px] font-semibold">{{ item.status }}</span></article><p v-if="!acknowledgements.length" class="text-sm text-slate-500">No stored acknowledgement responses yet.</p></div></section>

    <section v-else-if="activeTab === 'documents'" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div class="mb-5"><h2 class="font-bold text-slate-900">Guardian documents</h2><p class="mt-1 text-xs text-slate-500">Publish administrator-provided document references and review consent responses.</p></div><form class="grid grid-cols-1 gap-3 rounded-lg border border-violet-200 bg-violet-50/40 p-4 md:grid-cols-2" @submit.prevent="createDocument"><input v-model.trim="documentForm.title" required maxlength="200" placeholder="Document title" class="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input v-model.trim="documentForm.document_url" required maxlength="1000" placeholder="Document URL or approved reference" class="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><textarea v-model.trim="documentForm.description" maxlength="4000" rows="2" placeholder="Description" class="rounded-lg border border-slate-300 px-3 py-2 text-sm md:col-span-2"></textarea><label class="flex items-center gap-2 text-xs font-semibold text-slate-700"><input v-model="documentForm.consent_required" type="checkbox" /> Consent required</label><button type="submit" class="btn-primary w-fit px-4 py-2 text-xs font-semibold" :disabled="busyKey === 'document'">{{ busyKey === 'document' ? 'Creating…' : 'Create draft' }}</button></form><div class="mt-5 space-y-3"><article v-for="document in documents" :key="document.document_id" class="rounded-lg border border-slate-200 bg-slate-50 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold text-slate-900">{{ document.title }}</p><p class="mt-1 text-xs text-slate-500">{{ document.status }} · Version {{ document.version }} · {{ document.consent_required ? 'Consent required' : 'Read only' }}</p></div><div class="flex flex-wrap gap-2"><button v-if="document.status === 'Draft'" type="button" class="btn-primary px-3 py-2 text-[11px] font-semibold" @click="changeDocumentStatus(document, 'Published')">Publish</button><button v-if="document.status === 'Published'" type="button" class="btn-danger px-3 py-2 text-[11px] font-semibold" @click="changeDocumentStatus(document, 'Archived')">Archive</button></div></div><a :href="document.document_url" target="_blank" rel="noopener noreferrer" class="mt-2 inline-block text-xs font-semibold text-indigo-700 underline">Open reference</a><div v-if="documentResponses[document.document_id]?.length" class="mt-3 space-y-1 border-t border-slate-200 pt-3"><p class="text-[11px] font-bold uppercase tracking-wide text-slate-500">Responses</p><p v-for="response in documentResponses[document.document_id]" :key="response.response_id" class="text-xs text-slate-600">{{ response.guardian?.full_name }} · {{ response.student?.full_name || 'Account' }} · <strong>{{ response.decision }}</strong></p></div><button type="button" class="btn-secondary mt-3 px-3 py-2 text-[11px] font-semibold" @click="loadResponses(document)">Load responses</button></article><p v-if="!documents.length" class="text-sm text-slate-500">No guardian documents exist.</p></div></section>

    <section v-else class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div class="mb-4"><h2 class="font-bold text-slate-900">Guardian profile changes</h2><p class="mt-1 text-xs text-slate-500">Review proposed contact changes before updating authoritative guardian data.</p></div><div class="space-y-3"><article v-for="item in profileRequests" :key="item.request_id" class="rounded-lg border border-slate-200 bg-slate-50 p-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold text-slate-900">{{ item.guardian?.full_name }}</p><p class="mt-1 text-xs text-slate-500">Submitted {{ formatDate(item.created_at) }} · {{ item.reason }}</p><p class="mt-2 text-xs text-slate-700">{{ proposedSummary(item) }}</p></div><span class="rounded-full bg-amber-100 px-2 py-1 text-[10px] font-semibold text-amber-700">{{ item.status }}</span></div><div v-if="item.status === 'Pending'" class="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-[1fr_auto_auto]"><input v-model="profileDecisions[item.request_id]" placeholder="Decision note" class="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><button type="button" class="btn-primary px-3 py-2 text-xs font-semibold" @click="decideProfile(item, 'Approved')">Approve</button><button type="button" class="btn-danger px-3 py-2 text-xs font-semibold" @click="decideProfile(item, 'Rejected')">Reject</button></div></article><p v-if="!profileRequests.length" class="text-sm text-slate-500">No profile changes require review.</p></div></section>
  </section>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { authStore } from '../store/auth'
import { createAdminGuardianDocument, decideGuardianAppointment, decideGuardianProfileChange, fetchAdminDisciplineAcknowledgements, fetchAdminGuardianAppointments, fetchAdminGuardianCommunications, fetchAdminGuardianDocumentResponses, fetchAdminGuardianDocuments, fetchAdminGuardianProfileChangeRequests, respondToGuardianCommunication, updateAdminGuardianDocument } from '../api.js'

const token = () => authStore.token.value
const tabs = [{ key: 'communications', label: 'Communications' }, { key: 'appointments', label: 'Appointments' }, { key: 'discipline', label: 'Discipline' }, { key: 'documents', label: 'Documents & consent' }, { key: 'profiles', label: 'Profile changes' }]
const activeTab = ref('communications')
const communications = ref([]); const appointments = ref([]); const acknowledgements = ref([]); const documents = ref([]); const profileRequests = ref([])
const communicationResponses = reactive({}); const appointmentDecisions = reactive({}); const profileDecisions = reactive({}); const documentResponses = reactive({})
const documentForm = reactive({ title: '', description: '', document_url: '', consent_required: false })
const busyKey = ref(''); const errorMessage = ref(''); const successMessage = ref('')
function formatDate(value) { return value ? new Date(value).toLocaleDateString() : 'Not recorded' }
function formatDateTime(value) { return value ? new Date(value).toLocaleString() : 'Not recorded' }
function formatTime(value) { return value ? new Date(value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'Time unavailable' }
function proposedSummary(item) { return [item.proposed_full_name && `Name: ${item.proposed_full_name}`, item.proposed_email && `Email: ${item.proposed_email}`, item.proposed_phone && `Phone: ${item.proposed_phone}`, item.proposed_address && `Address: ${item.proposed_address}`, item.proposed_relationship && `Relationship: ${item.proposed_relationship}`].filter(Boolean).join(' · ') }
function handle(result, success) { if (!result.ok) { errorMessage.value = result.error || 'The operation failed.'; return false } successMessage.value = success; return true }
async function loadAll() { const results = await Promise.all([fetchAdminGuardianCommunications(token(), { status: 'Submitted' }), fetchAdminGuardianAppointments(token()), fetchAdminDisciplineAcknowledgements(token()), fetchAdminGuardianDocuments(token()), fetchAdminGuardianProfileChangeRequests(token(), { status: 'Pending' })]); if (results[0].ok) communications.value = results[0].data || []; if (results[1].ok) { appointments.value = results[1].data || []; appointments.value.forEach((item) => { appointmentDecisions[item.appointment_id] ||= { proposed_start_at: '', proposed_end_at: '', administrator_note: '' } }) }; if (results[2].ok) acknowledgements.value = results[2].data || []; if (results[3].ok) documents.value = results[3].data || []; if (results[4].ok) profileRequests.value = results[4].data || []; const failed = results.find((result) => !result.ok); if (failed) errorMessage.value = failed.error || 'Unable to load review queues.' }
async function respondCommunication(item, status) { busyKey.value = item.request_id; const result = await respondToGuardianCommunication(token(), item.request_id, { status, administrator_response: communicationResponses[item.request_id] || '' }); if (handle(result, 'Communication request updated.')) await loadAll(); busyKey.value = '' }
async function decideAppointment(item, status) { busyKey.value = item.appointment_id; const result = await decideGuardianAppointment(token(), item.appointment_id, { status, ...(appointmentDecisions[item.appointment_id] || {}) }); if (handle(result, 'Appointment request updated.')) await loadAll(); busyKey.value = '' }
async function createDocument() { busyKey.value = 'document'; const result = await createAdminGuardianDocument(token(), documentForm); if (handle(result, 'Document draft created.')) { documentForm.title = ''; documentForm.description = ''; documentForm.document_url = ''; documentForm.consent_required = false; await loadAll() } busyKey.value = '' }
async function changeDocumentStatus(document, status) { const result = await updateAdminGuardianDocument(token(), document.document_id, { status }); if (handle(result, `Document ${status.toLowerCase()}.`)) await loadAll() }
async function loadResponses(document) { const result = await fetchAdminGuardianDocumentResponses(token(), document.document_id); if (handle(result, 'Document responses loaded.')) documentResponses[document.document_id] = result.data || [] }
async function decideProfile(item, status) { const result = await decideGuardianProfileChange(token(), item.request_id, { status, decision_note: profileDecisions[item.request_id] || 'Reviewed by administrator.' }); if (handle(result, `Profile request ${status.toLowerCase()}.`)) await loadAll() }
onMounted(loadAll)
</script>
